/**  The work under way in the queue of syncs. */
export type SyncActivity_Deserialize = {
	/**  The open Repository's sync, or the tree of an Issue the user opened in it, while there is one. */
	open?: OpenSync_Deserialize | null,
	/**  The time GitHub's points come back, while the syncs wait for them. */
	paused_until: string | null,
	/**  The other Repositories with a sync queued, by name. They take turns with the open one (ADR 0015). */
	elsewhere: RepositoryName[],
};

/**  The work under way in the queue of syncs. */
export type SyncActivity_Serialize = {
	/**  The open Repository's sync, or the tree of an Issue the user opened in it, while there is one. */
	open: OpenSync_Serialize | null,
	/**  The time GitHub's points come back, while the syncs wait for them. */
	paused_until: string | null,
	/**  The other Repositories with a sync queued, by name. They take turns with the open one (ADR 0015). */
	elsewhere: RepositoryName[],
};

/**  The part of a sync under way, in the order a first sync runs them (ADR 0015). */
export type SyncPart = "your_work" | 
/**  The trees of the user's own Issues, and of any Issue they open. */
"trees" | "window" | 
/**  A small Repository's open items that last changed before the window. */
"older_open" | 
/**
 *  A refresh, or a sync that hasn't asked the store yet which it is. The status bar only mentions this
 *  when it has to wait.
 */
"refresh";

/**  How a query's text reads. */
export type Syntax = 
/**  Each character stands for itself. */
"literal" | 
/**  A regex in the Rust regex crate's syntax. */
"regex";

/**
 *  Sent when what the latest text search found may have changed: it waits, runs, found more or ended
 *  (#686). The window then asks `text_search_state`.
 */
export type TextSearchChanged = null;

/**
 *  What `[appearance] theme` in `settings.toml` asks the window to show (#755): the Theme `light_theme` or
 *  `dark_theme` names, whichever side the system is on, or one Theme whatever the system says. One key holds
 *  the choice, so the file can't follow the system and name a Theme as well. It reaches the file and the UI
 *  as the text the file holds: `"system"`, a mode, or a Theme's name, which no Theme may take.
 */
export type ThemeChoice = string;

/**  The theme the window shows, from `[appearance] theme` (#755). */
export type ThemeInForce = 
/**  The chosen theme of the side the system is on. A `theme` that names no usable theme gives this too. */
{ kind: "system" } | 
/**
 *  The chosen theme of `side`, whatever the system says, from a mode a file written before held. A pick
 *  in the theme picker replaces the mode.
 */
{ kind: "side"; side: ThemeKind } | 
/**  The theme named, whatever the system says. */
{ kind: "named"; name: ThemeName; side: ThemeKind };

/**  Whether a theme is for Windows' light side or its dark side. Each theme is one or the other, not a pair. */
export type ThemeKind = "light" | "dark";

/**
 *  A theme's name, as its file and `[appearance] light_theme` and `dark_theme` give it: a built-in theme's or
 *  one from the user's `themes` folder. It reaches the UI as a plain string.
 */
export type ThemeName = string;

/**
 *  The theme picker's pick for `[appearance] theme` (#756): follow the system, or show the Theme named, which
 *  `ThemeLibrary::choice` checks against the `themes` folder before it's saved. Settings › General's Theme
 *  picks one too (#757).
 */
export type ThemePick = { kind: "system" } | { kind: "named"; name: ThemeName };

/**
 *  A theme ready for the window: each token as a CSS variable, and the kind, which the root's
 *  `color-scheme` takes so scroll bars and form controls follow.
 */
export type ThemeView = {
	name: string,
	kind: ThemeKind,
	tokens: TokenView[],
};

/**
 *  The themes of each side, and the theme in force. Following the system, the window shows the chosen theme
 *  of the side the system is on, and turns to the other when the system does. The theme picker lists the
 *  rest (#518).
 */
export type Themes = {
	theme: ThemeInForce,
	light: SideThemes,
	dark: SideThemes,
	/**
	 *  What is wrong with the files of the `themes` folder, in words for the status bar, each naming its file
	 *  and, when the parser knows it, its line (#519).
	 */
	problems: string[],
};

